// Define in Name Manager (Formulas → Name Manager → New):
// Name: DDL_TAX       RefersTo: =LAMBDA(price, qty, tax, price * qty * (1 + tax))
// Name: DDL_PERIOD    RefersTo: =LAMBDA(d, TEXT(d, "YYYY-MM"))
// Name: DDL_VALID_ID  RefersTo: =LAMBDA(id, AND(ISNUMBER(id), id > 0, id = INT(id)))
// Name: DDL_YOY       RefersTo: =LAMBDA(curr, prior, IF(prior=0, "", (curr-prior)/prior))

// Call anywhere in the workbook:
=DDL_TAX(B2, C2, D2)
=FILTER(Table, DDL_VALID_ID(Table[ID]))
=MAP(Revenue[2026], Revenue[2025], DDL_YOY)

// Create a query named "fnNormalizeDate":
(rawDate as text) as date =>
  let
    trimmed  = Text.Trim(rawDate),
    parsed   = Date.FromText(trimmed, [Format = "M/d/yyyy"]),
    safe     = if Date.Year(parsed) > 2000 then parsed else null
  in
    safe

// Call from another query:
= Table.TransformColumns(Source, {
    {"RawDate", fnNormalizeDate, type nullable date}
  })

// In Excel: Table named "Parameters" with columns [Name] | [Value]
//   StartDate  | 2026-01-01
//   Region     | North
//   SourcePath | C:\data\sales\

// In M query:
let
  params     = Excel.CurrentWorkbook(){[Name="Parameters"]}[Content],
  getParam   = (n) => params{[Name=n]}[Value],
  startDate  = getParam("StartDate"),
  region     = getParam("Region"),
  source     = Csv.Document(File.Contents(getParam("SourcePath")))
in
  source

// Safe column transforms with fallback:
= Table.TransformColumns(Source, {
    {"RawDate",   each try Date.FromText(_)   otherwise null, type nullable date},
    {"Amount",    each try Number.FromText(_) otherwise 0,    type number}
  })

// Detailed error capture:
= Table.AddColumn(Source, "ParseResult",
    each let r = try Date.FromText([RawDate])
         in if r[HasError]
            then "PARSE ERROR: " & r[Error][Message]
            else Text.From(r[Value]))

// Tier 1 — Cell-level capture:
=IFERROR(XLOOKUP([ID], LookupTable[ID], LookupTable[Value]), "LOOKUP_MISS")

// Tier 2 — Row-level flag:
=IF(COUNTIF([@[Col1]:@[ColN]], "LOOKUP_MISS")>0, "EXCEPTION", "OK")

// Tier 3 — Exception log sheet:
=FILTER(DataTable, DataTable[RowStatus]="EXCEPTION", "No exceptions")

// Tier 4 — Operator summary:
=COUNTIF(DataTable[RowStatus], "EXCEPTION") & " items require review"

// Sheet structure:
// 01_Input    — data entry only
// 02_Calc     — formulas only, no print formatting
// 03_Report   — print-ready output, references 02_Calc, never enters data

// In 03_Report:
// Cell B3: ="Monthly Revenue Report — " & TEXT(Calc!WindowEnd, "MMMM YYYY")
// Cell B6: =Calc!SummaryMatrix  (spills into fixed print area)

// Pre-365: =A1:A10 in row 3 implicitly returns A3 (row intersection)
// Excel 365: =A1:A10 spills 10 values — DIFFERENT BEHAVIOR, no error

// THE FIX — explicit intersection with @:
=SUM(@A1:A100 * @B1:B100)   // Forces single-cell resolution in 365

// BETTER FIX — structured table references (version-safe):
=[@Amount] * [@Rate]         // Always resolves to the current row, all versions

// Column A contains "123" (text), 456 (number), " 789" (text + leading space)
=SUM(A:A)              // Returns 456 — silently ignores "123" and " 789"
=XLOOKUP(123, A:A, B:B)  // Returns #N/A — 123 (number) ≠ "123" (text)

// Detection:
=ISNUMBER(A2) * 1      // 0 = text, 1 = number

// Fixes:
=VALUE(TRIM(A2))       // Convert text number to number

// Anti-pattern: OFFSET driving a large dashboard range
=SUM(OFFSET(A1, 0, 0, COUNTA(A:A), 1))   // Volatile — recalculates on every edit

// Anti-pattern: INDIRECT for dynamic sheet references
=SUM(INDIRECT(C1 & "!A1:A1000"))          // Volatile

// Non-volatile replacements:
=SUM(DataTable[Amount])                    // Structured reference — not volatile
=INDEX(SheetData, 1, MATCH(C1, Headers,0)) // INDEX is not volatile

// Anti-pattern names:
// Data, Lookup, Range1, temp, x

// Governed naming convention: type_scope_purpose
tbl_Sales_Q1        // Table, Sales domain, Q1 scope
rng_Params_Dates    // Range, Parameters table, Date fields
fn_CalcNetRev       // Named LAMBDA function, Calc type, Net Revenue

// Stale name detection:
// Names showing "#REF!" in Name Manager → delete them

// The anti-pattern:
=VLOOKUP(A2, Products, 3, FALSE)
// "Return the value from column 3." — Insert a column before column 3 → wrong data. No error.

// The fix — XLOOKUP (Excel 365/2021):
=XLOOKUP(A2, Products[ID], Products[Price])
// Named column reference — position-independent

// The fix — INDEX/MATCH (all versions):
=INDEX(Products[Price], MATCH(A2, Products[ID], 0))
